    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
  </PropertyGroup>
  <ItemGroup>
    <PackageReference Include="xunit.v3" Version="1.1.0" />
  </ItemGroup>
</Project>
PROJ
cat > /tmp/checkctor/Program.cs <<'CS'
using System;
using System.Linq;
using System.Reflection;

var factType = typeof(Xunit.FactAttribute);
foreach (var c in factType.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance))
    Console.WriteLine("Fact: " + string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}")));

var theoryType = typeof(Xunit.TheoryAttribute);
foreach (var c in theoryType.GetConstructors(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance))
    Console.WriteLine("Theory: " + string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}")));
CS
dotnet run --project /tmp/checkctor 2>&1 | grep -E "^(Fact|Theory):"
